import{_ as a}from"./plugin-vue_export-helper-c27b6911.js";import{r as t,o as r,c as n,b as e,d as p,a as c,f as s,e as i}from"./app-baaad9db.js";const h={},_={href:"https://www.joanwestenberg.com/the-passive-income-trap-ate-a-generation-of-entrepreneurs/",target:"_blank",rel:"noopener noreferrer"},l=i('<h1 id="「被动收入」陷阱吞噬了一代创业者" tabindex="-1"><a class="header-anchor" href="#「被动收入」陷阱吞噬了一代创业者" aria-hidden="true">#</a> 「被动收入」陷阱吞噬了一代创业者</h1><p>作者：JA Westenberg | 2026年4月3日 | 8分钟阅读</p><hr><p>去年我和一个人喝咖啡，我就不说他真名了，他告诉我他在「创业」。我问他做什么的。代发货，玉石美容滚轮。</p><p>我让他说了两遍。</p><p>玉石美容滚轮。</p><p>他在阿里巴巴上找到货源，每个进价 1.2 美元，然后通过 Shopify 卖 29.99 美元。他自己从没用过一个。也不太明白这东西是干什么的，大概是促进淋巴循环？消水肿？他念「淋巴」这个词的方式，像是一个只读过却从未听过的人。</p><p>YouTube 上有人说玉石滚轮「正在走红」，账面上的利润看起来高得离谱，于是他「搭建」了一个网站，放上一张肤质水润的女人把绿色石头滚过颧骨的图片，开始每天花 50 美元跑 Facebook 广告。客户发邮件问东西在哪，从广州发货，要三到六周，有时还要更长，他就把从代发货论坛上找来的回复模板复制粘贴过去。他有一个 Google 文档，里面存满了预写好的客服话术。</p><p>他从没跟任何一个客户真正交谈过。</p><p>我跟你说，就是这样。</p><p>五个月后，他亏了 800 美元。</p><p>他跟我讲这一切的时候，神情好像自己发明了轮子。</p><p>我又给他买了一杯咖啡。我真的不知道还能做什么。</p><p>「玉石滚轮哥」成了我最常用的例子，用来说明整整一代准创业者在对待工作和金钱的思维方式上，到底出了多大的问题。一种特定的意识形态，我称之为「被动收入脑」，抓住了那些在性格和能力上最有可能创办真正企业的人，然后给了他们一套彻底扭曲的价值观。</p><p>大约在 2015 年到 2022 年之间，「被动收入」从一个枯燥的理财术语，变成了，我不知道怎么形容，一种救赎叙事。我是字面意思上的那种。如果你想书呆子一点，它甚至有末世论的意味。那个「末日审判」，就是你的「被动收入」超过每月支出、你可以永远辞职的那一天。人们谈论它，就带着那种劲儿。</p><p>当然，实际上真正在赚钱的人，赚的是「教人赚被动收入」的钱。这是一条咬尾蛇。一条已经在特拉华州完成公司注册、正在跑 Facebook 广告的咬尾蛇。</p><p>说辞大概是这样的：你，一个蠢货，现在是在用时间换钱。这是打工人做的事，打工人都是蠢货。（我在转述，但没夸大多少。）聪明人搭建「系统」。系统就是任何不需要你持续参与就能产生收入的东西。写一本电子书。建一个代发货店。开一门网课。搭几个联盟营销网站。</p><p>具体的载体不重要，因为重要的不是你做什么，而是结构。你要的是一台能在你睡觉时持续吐钱的机器，一旦你有了这台机器，你就自由了。</p><p>自由了干什么？坐在沙滩上，显然。他们每一个人都想坐在沙滩上。我从来没搞懂这一点。他们去过海滩吗？那里有沙子，会钻进所有地方。坐上三个小时，你就想做点任何其他的事了。</p><p>扯远了。</p><p>这种诱惑是真实的。谁不想要睡着了钱也在进来？</p><p>我他妈当然也想。非常想。但「被动收入」作为整个商业人生的核心哲学、作为你思考工作的方式，几乎是被精心设计用来生产垃圾的。</p><p>当你把「被动」当作优化目标，你就不再关心用户真正想要什么了。关心是主动的。关心需要时间。关心就是工作。</p><p>「在乎」，从定义上讲，就不是被动的。</p><p>2019 年到 2021 年间，大约有 70 万家新 Shopify 店铺开张。平台商户数量在两年内从大约 100 万增长到 170 万。其中约 90% 在第一年内倒闭了。这与其说是商业模式，不如说是一台绞肉机……</p><p>我们开始被无数没人真正在运营的生意淹没。代发货店铺六周的发货周期，客服只是复制粘贴的模板。那些把自己的「品牌名」，通常叫什么 ZENITHPRO 或者 AXELVIBE，永远全大写，永远莫名其妙地充满攻击性，贴在一个大蒜压碎器上的人，而这个大蒜压碎器和亚马逊同一页面上另外四百个大蒜压碎器毫无区别。AXELVIBE！贴在一个大蒜压碎器上！</p><p>还有那些联盟营销博客！数以十万计，塞满了经过 SEO 优化的产品测评，作者从没碰过、甚至没见过那些产品。从技术上讲算是商业行为，但没有给这个世界创造任何实际价值的分形废话。</p><p>杠杆是真实存在的，这一点我不否认。用时间换钱，和建立一个可以扩展的东西，这两者确实有区别。软件就是这样运作的。出版也是。你写一本书，卖出去很多本，没人说这是骗局。好，这部分他们理解对了！</p><p>错就错在，整个运动把「打造一个好产品并规模化」和「搭建任何一种不需要你参与就能榨取金钱的机制」混为一谈了。我不认为这种混淆是意外。我认为这种混淆本身就是目的。因为如果你是在教人创办真正的企业，你就必须直面那些枯燥而困难的问题，到底有没有人真的想要你在卖的东西。但如果你是在教人「建立被动收入流」，你就可以跳过这一切，直接去讲那些刺激的战术玩法。怎么跑 Facebook 广告，怎么在一个周末搭起一个 Shopify 店，怎么写出能操控人们购买他们不需要的东西的邮件序列。</p><p>没有人足够认真地谈过，被动收入运动对整个互联网的内容质量做了什么。如果你在过去五年里曾经搜索过「最好的[任何东西]」，然后得到了一堵几乎一模一样的榜单文章，全是同样的结构（「我们测试了 47 台搅拌机，省去你的麻烦！」），全是同样的推荐，全是指向同样亚马逊产品的链接，那你已经亲身体验了这些后果。</p><p>那些文章的作者并不在乎你是否买到了一台好搅拌机。他们在乎的是你是否点了他们的联盟链接，因为那才是被动收入的来源，而这种激励机制让诚实在经济上得不偿失。</p><p>对搅拌机的诚实评价是：「大多数搅拌机都差不多，买打折的就行，100 美元以下的差别基本上可以忽略不计。」这篇评测的联盟收入是零。所以没人写。</p><p>于是你看到的是「Vitamix A3500 是我们的第一名！」加上一个漂亮的联盟链接，作者这辈子没打过任何东西的汁。把这个乘以每一个产品类别，你就开始理解我们一直生活在其中的信息荒漠了。我们（至少部分地）搞坏了谷歌搜索结果，因为一支追求被动收入的大军，有着用听起来头头是道的垃圾填满互联网的动力。</p><p>（有人会反驳说谷歌本应过滤掉这些东西。好，也许。但是，「制造污染的人没有责任，因为环保局本应该发现」，这从来都不是什么有力的论点。）</p><p>我遇到过几十个聪明、有能力、充满干劲的人，他们把整个二十几岁都耗在了一个又一个被动收入计划上，而不是在积累真正的技能、建立真正的事业。模式总是一样的：在代发货店上耗六个月，失败，转向亚马逊 FBA，失败，转向开一门关于代发货的课程（当然），然后课程也卖不出去，因为到 2021 年，市面上大概已经有四万门关于代发货的课程了，而市场早在他们入场之前就已经饱和了。</p><p>在这整个过程中，他们离真正能创造经济价值的东西越来越远。那个东西是：找到真实的问题，为真实的人解决它，在乎到愿意留下来持续改进。那件枯燥的事。那件需要数年时间的事。那件，我要说得非常清楚，完全不被动的事。</p><p>我曾经看到有人问是否应该去做遛狗生意，得到的最高赞回答大意是：「遛狗没有规模效应，你应该去搭建一个遛狗平台。」这个人喜欢狗！他喜欢走路！他住在一个到处都是忙碌的专业人士养狗的街区！</p><p>但是「被动收入脑」已经深入到人们在网上谈论商业的方式里，以至于「做那件对你来说简单、显而易见、可行的事」被认为是幼稚的，而「为一项你从未真正做过的生意搭建一个科技平台」被认为是聪明的。</p><p>遛狗那个人，一周内就能开始盈利。</p><p>做 App 的那个人，六个月内会把积蓄烧光，最后只剩一个没有用户的落地页。</p><p>到 2020 年，被动收入的世界里到处爬满了骗局：在 YouTube 缩略图里摆着租来的兰博基尼的人，那些实际收入几乎全部来自于向其他渴望成为数字游民的人兜售数字游民梦想的「数字游民」，播客主持人们无休止地互相采访、互相背书，每个人都声称月入 3 万美元，却没有一个人能说清楚自己究竟生产了什么。到 2021 年左右，它开始看起来像一个分布式的、社会认可的传销。产品是不用工作的梦想。顾客是那些绝望到愿意为此付钱的人。</p><p>不是每个人都是愤世嫉俗的。这一点我真心相信。很多卖被动收入内容的人，相信他们自己说的那些。他们在某个垂直站点上取得过一些真实的成功，有段时间月入 3000 美元，这种事是有的，读了大家都在读的那些书，于是心想，好，我来教别人我的方法。为什么不呢。如果我 24 岁的时候，我几乎可以肯定自己也会这么做。</p><p>但是退一步看，你会发现这不过是一台巨大的机器，把人类的雄心壮志转化成噪音。联盟垃圾 / 代发货劣品 / 关于被动收入的电子书 / 关于课程的课程。互联网上的整整一层，全是充满自信的废话，由那些在一切事情上都进行了优化、唯独没有优化「做出值得购买的东西」的人生产出来的。</p><p>靠近顶端的人赚到了钱。其他所有人花了几个月甚至几年追逐一个海市蜃楼，最后什么都没有，只剩下一个忘记取消的 Shopify 订阅。他们以为是自己失败了。他们没有失败。是这套系统，每一套系统，让他们失败了。</p><p>真正能赚钱的方式从未改变。你找到人们真正需要的东西。你把提供这个东西这件事做好。你定一个公道的价格，然后即使在枯燥的时候、即使在你不想坚持的时候，你也继续出现。你花几年时间建立关系。你花几年时间建立声誉。这其中没有任何一件事是被动的，也从来都不曾是被动的！这一切都围绕着日复一日地在乎某件具体的事。我不认为有人找到过绕过这一点的方法，我也不认为有人会找到。</p><p>被动收入这件事，是一个关于不需要在乎任何事的幻想。</p><p>这是几乎任何事情的一个糟糕的基础。</p><p>那些联盟 SEO 博客正在被 AI 生成的内容屠杀。那些花了数年时间生产对人类毫无价值、只是针对算法进行了优化的内容的人们，正在被做着完全相同的事、只是更快更便宜的软件超越。Facebook 广告成本飙升，一并带走了代发货的淘金热。最大的被动收入大师们已经转向卖 AI 课程了。机器继续运转。只是换了一本新的宣传册。</p><p>但我注意到越来越多的人在谈论我称之为「真正在乎」的生意，做家具的人，开水管公司的人，写自己实际上在用的软件的人。那些对「你的生意为什么存在」这个问题的回答，不是「为了给我产生被动收入」的生意。这比那种「带着笔记本电脑坐在海滩上」的苦修要好用得多。</p><p>玉石滚轮哥，如果你看到这篇文章：我希望你找到了真正的东西。</p><p>我希望它让你忙个不停。</p>',51);function m(d,f){const o=t("ExternalLinkIcon");return r(),n("div",null,[e("p",null,[p("在hackernews上看到一篇文章 "),e("a",_,[p("被动收入陷阱"),c(o)]),p(" 挺有意思，分享出来")]),s("- more -"),l])}const k=a(h,[["render",m],["__file","passive-income.html.vue"]]);export{k as default};
